const W=60; const H=20; const K=6;
exports.init = (params, rng) => {
  const density = params.density ?? 0.4;
  const counterflowRatio = params.counterflowRatio ?? 0.5;
  const N = Math.floor(20 + density * 80);
  const nWest = Math.round(N * counterflowRatio);
  const nEast = N - nWest;
  const agents=[];
  for(let i=0;i<N;i++){
    const dir = i < nEast ? 1 : -1;
    const x = rng.range(0,W);
    const y = rng.range(0.5, H-0.5);
    const v0 = 0.9 + rng.range(0,0.4);
    agents.push({id:i, x, y, dir, vy:0, v0});
  }
  // shuffle y to avoid initial correlation
  for(let i=agents.length-1;i>0;i--){
    const j = rng.int(0,i);
    const tmpY = agents[i].y; agents[i].y = agents[j].y; agents[j].y = tmpY;
    const tmpX = agents[i].x; agents[i].x = agents[j].x; agents[j].x = tmpX;
  }
  return {agents, W, H, time:0};
};
exports.step = (state, params, rng) => {
  const A = params.avoidanceStrength ?? 1;
  const B = params.sideBias ?? 0;
  const W = state.W, H = state.H;
  const N = state.agents.length;
  const newAgents = state.agents.map(a=>({...a}));
  // compute lateral forces
  for(let i=0;i<N;i++){
    const ai = state.agents[i];
    let Fy = 0;
    if(ai.y < 2) Fy += (2 - ai.y)*1.4;
    if(ai.y > H-2) Fy += (H-2 - ai.y)*1.4;
    for(let j=0;j<N;j++){
      if(i===j) continue;
      const aj = state.agents[j];
      let dx = aj.x - ai.x;
      if(dx > W/2) dx -= W;
      if(dx < -W/2) dx += W;
      const dy = aj.y - ai.y;
      if(aj.dir !== ai.dir){
        if(ai.dir*dx > 0 && ai.dir*dx < 8 && Math.abs(dy) < 3){
          const mag = A * 2.6 * Math.exp(-Math.abs(dx)/2.4) * Math.exp(-Math.abs(dy)/1.0);
          let dirY;
          if(Math.abs(dy) > 0.18){
            dirY = -Math.sign(dy);
          } else {
            if(Math.abs(B) > 0.02){
              dirY = -ai.dir * Math.sign(B);
            } else {
              dirY = rng.next() > 0.5 ? 1 : -1;
            }
          }
          Fy += dirY * mag;
          if(Math.abs(B) > 0.02){
            Fy += -ai.dir * B * 0.55 * Math.exp(-Math.abs(dx)/3.2);
          }
        }
      } else {
        if(ai.dir*dx > 0 && ai.dir*dx < 6 && Math.abs(dy) < 2.6){
          const magFollow = A * 0.95 * Math.exp(-Math.abs(dx)/2.8) * Math.exp(-Math.abs(dy)/1.1);
          Fy += dy * magFollow * 0.7;
          if(Math.abs(dy) < 0.85 && Math.abs(dx) < 2.0){
            const rep = 0.7 * Math.exp(-Math.abs(dy)/0.45);
            Fy += -Math.sign(dy) * rep * (A>0?1:0);
            if(Math.abs(dy) < 0.12) Fy += (rng.next()>0.5?0.3:-0.3);
          }
        }
      }
    }
    let vy = ai.vy * 0.82 + Fy * 0.19 + (rng.next()-0.5)*0.05;
    if(vy > 2.2) vy=2.2;
    if(vy < -2.2) vy=-2.2;
    newAgents[i].vy = vy;
  }
  // update positions
  for(let i=0;i<N;i++){
    const ai = state.agents[i];
    let vy = newAgents[i].vy;
    let y = ai.y + vy * 0.32;
    if(y < 0.5){ y=0.5; newAgents[i].vy *= -0.25; }
    if(y > H-0.5){ y=H-0.5; newAgents[i].vy *= -0.25; }
    newAgents[i].y = y;
    // speed reduction if blocked head-on
    let speedFactor = 1;
    for(let j=0;j<N;j++){
      if(i===j) continue;
      const aj = state.agents[j];
      if(aj.dir !== ai.dir){
        let dx = aj.x - ai.x;
        if(dx > W/2) dx -= W;
        if(dx < -W/2) dx += W;
        const dy = aj.y - ai.y;
        if(ai.dir*dx > 0 && ai.dir*dx < 1.7 && Math.abs(dy) < 0.85){
          speedFactor = 0.22;
          break;
        }
      }
    }
    let x = ai.x + ai.dir * ai.v0 * 0.5 * speedFactor;
    x = ((x % W) + W) % W;
    newAgents[i].x = x;
  }
  return {agents:newAgents, W, H, time: state.time+1};
};
exports.observe = (state, params) => {
  const Kbins = K;
  const H = state.H;
  const W = state.W;
  const bins = Array(Kbins).fill(0).map(()=>({east:0, west:0}));
  for(const a of state.agents){
    let b = Math.floor(a.y / H * Kbins);
    if(b<0) b=0; if(b>=Kbins) b=Kbins-1;
    if(a.dir===1) bins[b].east++; else bins[b].west++;
  }
  const f = bins.map(b=>{
    const tot=b.east+b.west;
    if(tot===0) return 0.5;
    return b.east/tot;
  });
  const mean = f.reduce((s,v)=>s+v,0)/Kbins;
  const variance = f.reduce((s,v)=>s+(v-mean)*(v-mean),0)/Kbins;
  const laneOrderParameter = Math.max(0, Math.min(1, variance*4));
  let count=0;
  const N=state.agents.length;
  for(let i=0;i<N;i++){
    for(let j=i+1;j<N;j++){
      const ai=state.agents[i], aj=state.agents[j];
      if(ai.dir===aj.dir) continue;
      let dx = aj.x - ai.x;
      if(dx > W/2) dx -= W;
      if(dx < -W/2) dx += W;
      const dy = aj.y - ai.y;
      if(Math.abs(dx) < 2.5 && Math.abs(dy) < 1.0) count++;
    }
  }
  const headOnCollisionRate = count / Math.max(1,N);
  let sumV=0;
  for(const a of state.agents) sumV += a.v0;
  const avgSpeed = sumV / Math.max(1,N) * (1 - headOnCollisionRate*0.6);
  return {laneOrderParameter, headOnCollisionRate, avgSpeed};
};
exports.view = (state, params) => {
  return {
    kind: 'bodies',
    bounds: {x:0, y:0, w: state.W, h: state.H},
    bodies: state.agents.map(a=>({
      id: a.id,
      x: a.x,
      y: a.y,
      radius: 0.72,
      color: a.dir===1 ? '#3b82f6' : '#ef4444'
    }))
  };
};
